#include <iostream>
#include <iomanip>
#include <string>
#include <vector>
#include <cstdint>
float source_decimal(const std::string &s) {
    uint32_t whole=0;
    int exponent=0, count=0;
    bool fractional=false;
    bool negative=s.front()=='-';
    for(char c: s) {
        if(c=='+' || c=='-') continue;
        if(c=='.') { fractional=true; continue; }
        ++count;
        if(count<=8) { whole=whole*10+(c-'0'); if(fractional)--exponent; }
        else if(!fractional)++exponent;
    }
    float result=static_cast<float>(whole);
    if(result!=0) {
        while(exponent<=-2) {result*=.01f; exponent+=2;}
        if(exponent<0)result*=.1f;
        else while(exponent-->0)result*=10.f;
    }
    return negative?-result:result;
}
int main() {
  std::vector<std::string> cases={"123456789","0.000000001","-0.000000001","000000001","0.123456789","1.23456789","0.00000001","-123.456789","99999999","100000001","12.3456","+0.05"};
  std::cout<<std::setprecision(17)<<"[\n";
  bool first=true;
  for(auto s:cases) {if(!first)std::cout<<",\n";first=false;std::cout<<"{\"decimal\":\""<<s<<"\",\"avr_float32\":"<<source_decimal(s)<<"}";}
  std::cout<<"\n]\n";
}
